export interface EventTypeRow {
  id: string;
  key: string;
  labelHe: string;
  labelEn: string;
  colorHex: string;
  glyph: string;
}

/** The fields staff edit. The key is generated by the server and never shown. */
export type EventTypeDraft = Pick<EventTypeRow, "labelHe" | "labelEn" | "colorHex" | "glyph">;

/** Translation keys (admin.eventTypes.*) for failures shown next to the row. */
export type EventTypeErrorKey = "errorSave" | "errorDelete" | "errorReorder" | "inUse" | "errorDemo";

export type ApiResult<T = undefined> =
  | { ok: true; data: T }
  | { ok: false; error: EventTypeErrorKey };
